mapper.select:
SELECT * FROM (
    SELECT N.ID NOTIFICATION_ID, N.TYPE, R.REVIEW_ID, R.CONTENT_ID,
        COALESCE(A.USERNAME, '탈퇴한 사용자') ACTOR_NICKNAME, N.CREATED_AT, N.READ_AT
    FROM REVIEW_NOTIFICATION N
    LEFT JOIN REVIEW R ON R.REVIEW_ID = N.REVIEW_ID AND R.DEL_YN = 'N'
    LEFT JOIN USERS A ON A.USER_ID = N.ACTOR_ID AND A.DEL_YN = 'N' AND A.BAN_YN = 'N'
    WHERE N.USER_ID = #{userId}

        AND (N.CREATED_AT < #{createdAt} OR (N.CREATED_AT = #{createdAt} AND N.ID < #{id}))

    ORDER BY N.CREATED_AT DESC, N.ID DESC
) WHERE ROWNUM <= #{limit}
